import collections

def top_k_frequent(nums, k):
    if not nums or k <= 0:
        return []
    freq = collections.Counter(nums)
    seen = set()
    result = []
    for num in nums:
        if num not in seen:
            seen.add(num)
            result.append(num)
    result.sort(key=lambda x: freq[x], reverse=True)
    return result[:k]

